import{_ as i,l as o,o as a,c as n,v as r,p as l,x as s,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"挂起与恢复","description":"","frontmatter":{"title":"挂起与恢复","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/suspend-resume.md","filePath":"cs/suspend-resume.md","lastUpdated":1789023840000}'),u={name:"cs/suspend-resume.md"};function h(f,e,m,_,E,A){const t=o("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="挂起与恢复" tabindex="-1">挂起与恢复 <a class="header-anchor" href="#挂起与恢复" aria-label="Permalink to &quot;挂起与恢复&quot;">​</a></h1><div class="epigraph"><p>休眠把设备 freeze、内存写入交换或固件睡眠态；恢复按相反顺序解冻，时间与驱动质量决定成败。</p><footer>—— 据 Linux power 文档对 suspend/hibernation 的说明；ACPI S3/S4；[cpuidle](/cs/cpuidle-cstate) 为浅睡眠对照</footer></div><p><a href="/cs/udev-hotplug">udev</a> 管插拔。<a href="/cs/cpuidle-cstate">C-state</a> 是核闲。缺口是 <strong>整机睡眠</strong>：freeze 任务、设备 <code>suspend</code> 回调、与休眠镜像。安全/启动课序在此收口，观测下一课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>S3：RAM 自刷新，外设断电。S4：内存写盘。freeze：用户进程停。缺口：驱动未实现 suspend 则失败或丢设备；与 <a href="/cs/preempt-rt">PREEMPT_RT</a> 延迟；加密根要恢复路径解封。本课不把每家 BIOS 坑列出。</p><p><span class="marginnote">userspace freeze 与 freezer cgroup 亲戚。对象是电源状态机，不是调度时间片。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>echo mem &gt; /sys/power/state</code> → freeze → 设备 suspend → 平台睡眠。唤醒：resume 相反。对照 <a href="/cs/memory-hotplug">热插拔内存</a>：睡眠中 DMA 必须停。对照 <a href="/cs/nvme-driver">NVMe</a>：要保存队列状态或重置。对照 TPM：PCR 在 S3 可能变化，策略要设计。</p>',8)),(a(),l(c,null,{default:s(()=>[d(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22suspend%22%5D%20--%3E%20FRZ%5B%22%E5%86%BB%E7%BB%93%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20FRZ%20--%3E%20DEV%5B%22%E8%AE%BE%E5%A4%87%20suspend%22%5D%0A%20%20DEV%20--%3E%20PLAT%5B%22%E5%B9%B3%E5%8F%B0%20S3%2FS4%22%5D%0A%20%20WAKE%5B%22%E5%94%A4%E9%86%92%22%5D%20--%3E%20REV%5B%22resume%20%E9%80%86%E5%BA%8F%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>挂起把「看起来关机、RAM 还在」收成驱动协议。失败表现为 USB 死、时钟错、无法唤醒。不要写成笔记本评测。与 <a href="/cs/fsync">fsync</a>：休眠前应刷盘。与 <a href="/cs/kpti-os">KPTI</a>：恢复后页表仍要正确。</p><p>hibernate 镜像是攻击面，需加密。</p><p>实现上：freeze 用户进程后还要 freeze 内核线程的可冻集合。驱动 resume 顺序与父子设备相反。hibernate 镜像未加密等于 RAM 落盘明文。 读法上只引用<a href="/cs/udev-hotplug">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>挂起与恢复</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 runtime PM 的自动闲。不保证虚拟机 S3。下一课序观测：printk。</p><p>版本字段会变，课序钉的是机制对象「挂起与恢复」，不是某一主线内核的结构体名。 后课默认：整机睡眠走 freeze+设备回调。内核如何把消息打出来，下一课 printk。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>suspend/hibernate 冻结任务并回调驱动。</li><li>比 C-state 深，依赖固件与驱动。</li><li>printk 是下一课序。</li><li>出处：Linux power；ACPI；设备 PM。</li></ul>',11))])}const S=i(u,[["render",h]]);export{P as __pageData,S as default};
